'use client';

import * as React from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { Building2, CheckCircle2, ChevronRight, ClipboardList, LayoutDashboard, LogOut, Package, Pencil, Plus, ShieldCheck, ShoppingBag, Store, Trash2, Users, XCircle } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { toast } from '@/components/ui/Toast';
import { GlobalLayout } from '@/components/layout/GlobalLayout';
import { useAuth } from '@/lib/providers/AuthProvider';
import { api } from '@/lib/api';
import { DEMO_VENDORS, getProductVendor, getVendor, getVendorProducts } from '@/lib/data/mockVendors';
import { PRODUCTS } from '@/lib/data/products';
import { formatINR } from '@/utils/format';

type PortalMode = 'dashboard' | 'products' | 'add' | 'orders' | 'profile' | 'admin' | 'store';
type OrderStatus = 'Pending' | 'Processing' | 'Shipped' | 'Completed';

interface LocalProduct { id: string; name: string; sku: string; price: number; stock: number; image: string; vendorId: string; status: 'Active' | 'Draft'; }
interface LocalOrder { id: string; customer: string; product: string; quantity: number; total: number; status: OrderStatus; vendorId: string; }

const PRODUCTS_KEY = 'electrohub_vendor_products';
const ORDERS_KEY = 'electrohub_vendor_orders';
const seededProducts: LocalProduct[] = PRODUCTS.slice(0, 7).map((product) => ({ id: product.id, name: product.name, sku: product.sku, price: product.sellingPrice, stock: product.stock, image: product.images[0]?.url ?? '', vendorId: getProductVendor(product.id).vendorId, status: 'Active' }));
const seededOrders: LocalOrder[] = [
  { id: 'EH-10023', customer: 'Rahul Sharma', product: 'Arduino UNO R4 WiFi', quantity: 2, total: 4998, status: 'Pending', vendorId: 'vendor-techtron' },
  { id: 'EH-10019', customer: 'Meera Nair', product: 'Arduino Mega 2560 R3', quantity: 1, total: 1899, status: 'Processing', vendorId: 'vendor-techtron' },
  { id: 'EH-10011', customer: 'Aarav Singh', product: 'Arduino Nano Every', quantity: 3, total: 2247, status: 'Completed', vendorId: 'vendor-techtron' },
];

function readLocal<T>(key: string, fallback: T): T { if (typeof window === 'undefined') return fallback; try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; } catch { return fallback; } }
function writeLocal(key: string, value: unknown) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* demo storage unavailable */ } }

function Guard({ children, allowed }: { children: React.ReactNode; allowed: Array<'vendor' | 'admin'> }) {
  const router = useRouter();
  const { user, isLoggedIn } = useAuth();
  const hasAccess = user?.role === 'vendor' || user?.role === 'admin' ? allowed.includes(user.role) : false;
  React.useEffect(() => { if (!isLoggedIn) router.replace('/login'); else if (!hasAccess) router.replace('/'); }, [allowed, hasAccess, isLoggedIn, router]);
  if (!isLoggedIn || !hasAccess) return <GlobalLayout><div className="container-fluid py-24 text-center"><ShieldCheck className="mx-auto mb-4 text-[var(--primary)]" size={36} /><h1 className="text-2xl font-bold text-[var(--text)]">Access restricted</h1><p className="mt-2 text-sm text-[var(--text-muted)]">This workspace is available to approved marketplace staff.</p></div></GlobalLayout>;
  return <>{children}</>;
}

function PortalShell({ children, mode }: { children: React.ReactNode; mode: PortalMode }) {
  const { user, logout } = useAuth();
  const links = [{ label: 'Dashboard', href: '/vendor/dashboard', icon: LayoutDashboard, mode: 'dashboard' }, { label: 'My Products', href: '/vendor/products', icon: Package, mode: 'products' }, { label: 'Add Product', href: '/vendor/products/add', icon: Plus, mode: 'add' }, { label: 'Orders', href: '/vendor/orders', icon: ShoppingBag, mode: 'orders' }, { label: 'Business Profile', href: '/vendor/profile', icon: Building2, mode: 'profile' }];
  return <GlobalLayout><div className="container-fluid py-8"><div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--primary)]">Marketplace workspace</p><h1 className="mt-1 text-2xl font-bold font-display text-[var(--text)]">{mode === 'dashboard' ? `Welcome, ${user?.name?.split(' ')[0] ?? 'Vendor'}` : 'Vendor workspace'}</h1></div><Button variant="ghost" size="sm" leftIcon={<LogOut size={14} />} onClick={logout}>Logout</Button></div><div className="grid gap-6 lg:grid-cols-[220px_minmax(0,1fr)]"><aside className="h-fit rounded-2xl border border-[var(--border)] bg-[var(--background-card)] p-3 shadow-[var(--shadow-card)]"><div className="mb-3 flex items-center gap-3 rounded-xl bg-[var(--surface)] p-3"><Store size={18} className="text-[var(--primary)]" /><div><p className="text-[10px] text-[var(--text-subtle)]">Seller account</p><p className="text-sm font-semibold text-[var(--text)]">Techtron Electronics</p></div></div><nav className="space-y-1">{links.map(({ label, href, icon: Icon, mode: linkMode }) => <Link key={href} href={href} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${mode === linkMode ? 'bg-[var(--primary)]/10 text-[var(--primary)] font-semibold' : 'text-[var(--text-muted)] hover:bg-[var(--surface-hover)]'}`}><Icon size={15} />{label}</Link>)}</nav></aside><main>{children}</main></div></div></GlobalLayout>;
}

export function VendorDashboard() { return <Guard allowed={['vendor']}><PortalShell mode="dashboard"><DashboardContent /></PortalShell></Guard>; }
function DashboardContent() { const products = readLocal(PRODUCTS_KEY, seededProducts); const orders = readLocal(ORDERS_KEY, seededOrders); const sales = orders.reduce((sum, order) => sum + order.total, 0); const stats = [{ label: 'Total Products', value: products.length, icon: Package }, { label: 'Active Products', value: products.filter((p) => p.status === 'Active').length, icon: CheckCircle2 }, { label: 'Pending Orders', value: orders.filter((o) => o.status === 'Pending').length, icon: ClipboardList }, { label: 'Total Sales', value: formatINR(sales), icon: ShoppingBag }]; return <div className="space-y-6"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(({ label, value, icon: Icon }) => <Card key={label} className="p-5"><Icon size={18} className="text-[var(--primary)]" /><p className="mt-4 text-sm text-[var(--text-muted)]">{label}</p><p className="mt-1 text-2xl font-bold text-[var(--text)]">{value}</p></Card>)}</div><Card className="overflow-hidden"><div className="border-b border-[var(--border)] px-5 py-4"><h2 className="font-semibold text-[var(--text)]">Recent orders</h2></div><OrderTable orders={orders.slice(0, 3)} /></Card></div>; }

export function VendorProducts({ add = false }: { add?: boolean }) { return <Guard allowed={['vendor']}><PortalShell mode={add ? 'add' : 'products'}>{add ? <AddProductForm /> : <ProductManager />}</PortalShell></Guard>; }
function ProductManager() { const [products, setProducts] = React.useState<LocalProduct[]>(() => readLocal(PRODUCTS_KEY, seededProducts)); const remove = (id: string) => { const next = products.filter((product) => product.id !== id); setProducts(next); writeLocal(PRODUCTS_KEY, next); toast.success('Product deleted'); }; return <div className="space-y-5"><div className="flex items-center justify-between gap-3"><div><h2 className="text-xl font-bold text-[var(--text)]">My Products</h2><p className="mt-1 text-sm text-[var(--text-muted)]">Manage your marketplace catalogue.</p></div><Link href="/vendor/products/add"><Button size="sm" leftIcon={<Plus size={14} />}>Add Product</Button></Link></div><Card className="overflow-hidden"><div className="divide-y divide-[var(--border)]">{products.map((product) => <div key={product.id} className="flex flex-wrap items-center gap-4 p-4"><img src={product.image} alt="" className="h-14 w-14 rounded-lg bg-[var(--background-alt)] object-contain p-1" /><div className="min-w-[180px] flex-1"><p className="font-semibold text-[var(--text)]">{product.name}</p><p className="mt-1 text-xs text-[var(--text-muted)]">SKU: {product.sku}</p></div><span className="text-sm font-semibold text-[var(--text)]">{formatINR(product.price)}</span><span className="text-sm text-[var(--text-muted)]">Stock: {product.stock}</span><Badge variant={product.status === 'Active' ? 'success' : 'default'}>{product.status}</Badge><button className="text-[var(--text-muted)] hover:text-[var(--danger)]" onClick={() => remove(product.id)} aria-label={`Delete ${product.name}`}><Trash2 size={15} /></button></div>)}</div></Card></div>; }

interface AddForm { name: string; category: string; brand: string; sku: string; price: string; stock: string; description: string; }
function AddProductForm() { const router = useRouter(); const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<AddForm>(); const onSubmit = (data: AddForm) => { const products = readLocal(PRODUCTS_KEY, seededProducts); const next: LocalProduct = { id: `demo-${crypto.randomUUID()}`, name: data.name, sku: data.sku, price: Number(data.price), stock: Number(data.stock), image: '/images/products/arduino-nano-every.svg', vendorId: 'vendor-techtron', status: 'Active' }; writeLocal(PRODUCTS_KEY, [...products, next]); toast.success('Product added to your catalogue'); router.push('/vendor/products'); }; return <Card className="max-w-3xl p-6"><h2 className="text-xl font-bold text-[var(--text)]">Add Product</h2><p className="mt-1 mb-6 text-sm text-[var(--text-muted)]">New demo products are saved locally for the marketplace presentation.</p><form onSubmit={handleSubmit(onSubmit)} className="grid gap-4 sm:grid-cols-2"><Input label="Product Name" error={errors.name?.message} {...register('name', { required: 'Product name is required' })} /><Input label="Category" {...register('category', { required: true })} /><Input label="Brand" {...register('brand', { required: true })} /><Input label="SKU" {...register('sku', { required: true })} /><Input label="Price" type="number" error={errors.price?.message} {...register('price', { required: 'Price is required' })} /><Input label="Stock" type="number" {...register('stock', { required: true })} /><div className="sm:col-span-2"><Input label="Description" {...register('description')} /></div><div className="sm:col-span-2"><Button type="submit" isLoading={isSubmitting} leftIcon={<Plus size={15} />}>Add Product</Button></div></form></Card>; }

export function VendorOrders() { return <Guard allowed={['vendor']}><PortalShell mode="orders"><OrdersContent /></PortalShell></Guard>; }
function OrdersContent() { const [orders, setOrders] = React.useState<LocalOrder[]>(() => readLocal(ORDERS_KEY, seededOrders)); const update = (id: string, status: OrderStatus) => { const next = orders.map((order) => order.id === id ? { ...order, status } : order); setOrders(next); writeLocal(ORDERS_KEY, next); toast.success(`Order marked ${status.toLowerCase()}`); }; return <div className="space-y-5"><h2 className="text-xl font-bold text-[var(--text)]">Orders</h2><Card className="overflow-hidden"><OrderTable orders={orders} onStatus={update} /></Card></div>; }
function OrderTable({ orders, onStatus }: { orders: LocalOrder[]; onStatus?: (id: string, status: OrderStatus) => void }) { return <div className="divide-y divide-[var(--border)]">{orders.map((order) => <div key={order.id} className="flex flex-wrap items-center gap-4 p-4"><div className="min-w-[140px] flex-1"><p className="font-semibold text-[var(--text)]">Order #{order.id}</p><p className="mt-1 text-xs text-[var(--text-muted)]">Customer: {order.customer}</p><p className="text-xs text-[var(--text-muted)]">{order.product} × {order.quantity}</p></div><span className="font-semibold text-[var(--text)]">{formatINR(order.total)}</span><Badge variant={order.status === 'Completed' ? 'success' : order.status === 'Pending' ? 'warning' : 'info'}>{order.status}</Badge>{onStatus && <select value={order.status} onChange={(event) => onStatus(order.id, event.target.value as OrderStatus)} className="rounded-lg border border-[var(--border)] bg-[var(--background-card)] px-2 py-1.5 text-xs text-[var(--text)]"><option>Pending</option><option>Processing</option><option>Shipped</option><option>Completed</option></select>}</div>)}</div>; }

export function VendorProfilePage() { const [profile, setProfile] = React.useState<Record<string, string> | null>(null); React.useEffect(() => { const token = localStorage.getItem('electrohub_access_token') ?? ''; api.get<Record<string, string>>('/vendor/profile/', { token }).then(setProfile).catch(() => setProfile({ business_name: 'Techtron Electronics', business_address: '12 Maker Street', city: 'Bengaluru', state: 'Karnataka', pincode: '560001', gstin: '29AABCT1234F1Z5', description: 'Reliable development boards and embedded electronics.', website: 'https://techtron.in', status: 'pending' })); }, []); const save = async (event: React.FormEvent<HTMLFormElement>) => { event.preventDefault(); const body = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, string>; try { await api.patch('/vendor/profile/', body, { token: localStorage.getItem('electrohub_access_token') ?? '' }); toast.success('Business profile updated'); setProfile(body); } catch { setProfile(body); toast.success('Profile saved for this demo'); } }; if (!profile) return <GlobalLayout><div className="container-fluid py-24 text-center text-sm text-[var(--text-muted)]">Loading business profile...</div></GlobalLayout>; return <Guard allowed={['vendor']}><PortalShell mode="profile"><Card className="max-w-3xl p-6"><div className="mb-6 flex items-center justify-between"><div><h2 className="text-xl font-bold text-[var(--text)]">Business Profile</h2><p className="mt-1 text-sm text-[var(--text-muted)]">Your vendor application is <strong className="text-amber-600">{profile.status ?? 'pending'}</strong>.</p></div><Badge variant="warning">{profile.status ?? 'Pending'}</Badge></div><form onSubmit={save} className="grid gap-4 sm:grid-cols-2">{['business_name','business_address','city','state','pincode','gstin','website','description'].map((field) => <Input key={field} label={field.replace('_', ' ').replace(/^./, (letter) => letter.toUpperCase())} name={field} defaultValue={profile[field] ?? ''} />)}<div className="sm:col-span-2"><Button type="submit" leftIcon={<Pencil size={14} />}>Save Profile</Button></div></form></Card></PortalShell></Guard>; }

export function VendorRegistration() { const router = useRouter(); const [message, setMessage] = React.useState(''); const [error, setError] = React.useState(''); const { register, handleSubmit, formState: { errors, isSubmitting } } = useForm<Record<string, string>>(); const submit = async (data: Record<string, string>) => { setError(''); const { confirmPassword, businessName, businessAddress, ...rest } = data; const payload = { ...rest, confirm_password: confirmPassword, business_name: businessName, business_address: businessAddress }; try { await api.post('/vendor/register/', payload); setMessage('Vendor application submitted successfully. Your account is pending admin approval.'); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Registration failed. Please try again.'); } }; if (message) return <GlobalLayout><div className="container-fluid py-24"><Card className="mx-auto max-w-lg p-8 text-center"><CheckCircle2 className="mx-auto mb-4 text-[var(--success)]" size={42} /><h1 className="text-2xl font-bold text-[var(--text)]">Application received</h1><p className="mt-3 text-sm text-[var(--text-muted)]">{message}</p><Button className="mt-6" onClick={() => router.push('/login')}>Continue to sign in</Button></Card></div></GlobalLayout>; return <GlobalLayout><div className="container-fluid py-10"><Card className="mx-auto max-w-3xl p-6 sm:p-8"><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--primary)]">Sell on ElectroHub</p><h1 className="mt-2 text-2xl font-bold text-[var(--text)]">Vendor registration</h1><p className="mt-1 mb-7 text-sm text-[var(--text-muted)]">Apply to list electronics with the ElectroHub marketplace.</p>{error && <div className="mb-5 rounded-lg bg-[var(--danger-bg)] p-3 text-sm text-[var(--danger)]">{error}</div>}<form onSubmit={handleSubmit(submit)} className="grid gap-4 sm:grid-cols-2">{[['businessName','Business Name'],['firstName','First Name'],['lastName','Last Name'],['email','Email'],['phone','Phone'],['password','Password'],['confirmPassword','Confirm Password'],['businessAddress','Business Address'],['city','City'],['state','State'],['pincode','Pincode'],['gstin','GSTIN'],['description','Description']].map(([name,label]) => <Input key={name} label={label} type={name.toLowerCase().includes('password') ? 'password' : 'text'} error={errors[name]?.message} {...register(name, { required: `${label} is required` })} />)}<div className="sm:col-span-2"><Button type="submit" isLoading={isSubmitting} leftIcon={<Building2 size={15} />}>Submit application</Button></div></form></Card></div></GlobalLayout>; }

export function AdminVendors() { const [vendors, setVendors] = React.useState<any[]>(DEMO_VENDORS.map((vendor) => ({ ...vendor, id: vendor.id, business_name: vendor.businessName, name: vendor.businessName, email: vendor.email }))); const update = async (id: string, action: 'approve' | 'reject' | 'suspend') => { try { await api.patch(`/admin/vendors/${id}/${action}/`, action === 'reject' ? { reason: 'Please provide additional business verification.' } : {}, { token: localStorage.getItem('electrohub_access_token') ?? '' }); } catch { /* local demo fallback */ } setVendors((current) => current.map((vendor) => vendor.id === id ? { ...vendor, status: action === 'approve' ? 'approved' : action === 'reject' ? 'rejected' : 'suspended' } : vendor)); toast.success(`Vendor ${action}d`); }; return <Guard allowed={['admin']}><GlobalLayout><div className="container-fluid py-10"><div className="mb-6"><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--primary)]">Administration</p><h1 className="mt-1 text-2xl font-bold text-[var(--text)]">Vendor Applications</h1></div><Card className="overflow-hidden"><div className="divide-y divide-[var(--border)]">{vendors.map((vendor) => <div key={vendor.id} className="flex flex-wrap items-center gap-4 p-5"><div className="flex min-w-[200px] flex-1 items-center gap-3"><div className="flex h-10 w-10 items-center justify-center rounded-xl bg-[var(--primary)]/10 text-[var(--primary)]"><Users size={17} /></div><div><p className="font-semibold text-[var(--text)]">{vendor.business_name}</p><p className="text-xs text-[var(--text-muted)]">{vendor.email} · {vendor.city}</p></div></div><span className="text-xs text-[var(--text-muted)]">GSTIN: {vendor.gstin}</span><Badge variant={vendor.status === 'approved' ? 'success' : vendor.status === 'rejected' ? 'danger' : 'warning'}>{vendor.status}</Badge><div className="flex gap-2">{vendor.status !== 'approved' && <Button size="sm" onClick={() => update(vendor.id, 'approve')} leftIcon={<CheckCircle2 size={13} />}>Approve</Button>}{vendor.status !== 'rejected' && <Button size="sm" variant="secondary" onClick={() => update(vendor.id, 'reject')} leftIcon={<XCircle size={13} />}>Reject</Button>}{vendor.status === 'approved' && <Button size="sm" variant="ghost" onClick={() => update(vendor.id, 'suspend')}>Suspend</Button>}</div></div>)}</div></Card></div></GlobalLayout></Guard>; }

export function VendorStore({ vendorId }: { vendorId: string }) { const vendor = getVendor(vendorId); const products = getVendorProducts(vendorId, PRODUCTS); return <GlobalLayout><div className="container-fluid py-10"><Card className="mb-8 p-6"><div className="flex flex-wrap items-center gap-4"><div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-[var(--primary)]/10 text-[var(--primary)]"><Store size={28} /></div><div><h1 className="text-2xl font-bold text-[var(--text)]">{vendor.businessName}</h1><p className="mt-1 text-sm text-[var(--text-muted)]">{vendor.city} · {vendor.description}</p><p className="mt-2 text-sm"><span className="text-[var(--success)]">✓ Verified Vendor</span><span className="ml-3 text-amber-500">★ {vendor.rating}</span></p></div></div></Card><div className="mb-4 flex items-center justify-between"><h2 className="text-xl font-bold text-[var(--text)]">Products from this store</h2><span className="text-sm text-[var(--text-muted)]">{products.length} products</span></div><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{products.map((product) => <Link key={product.id} href={`/product/${product.id}`}><Card className="h-full p-4 transition-shadow hover:shadow-[var(--shadow-card-hov)]"><img src={product.images[0]?.url} alt={product.name} className="aspect-square w-full object-contain" /><p className="mt-3 text-xs text-[var(--primary)]">{product.brand}</p><h3 className="mt-1 font-semibold text-[var(--text)]">{product.name}</h3><p className="mt-2 font-bold text-[var(--text)]">{formatINR(product.sellingPrice)}</p></Card></Link>)}</div></div></GlobalLayout>; }
